Identify the bug in this code and explain how to fix it:

```typescript
interface User {
  id: number;
  name: string;
  email: string;
}

class UserManager {
  private users: User[] = [];
  private isLoading: boolean = false;

  async fetchUsers(): Promise<void> {
    this.isLoading = true;
    try {
      const response = await fetch('/api/users');
      const data = await response.json();
      this.users = data;
    } finally {
      this.isLoading = false;
    }
  }

  async addUser(user: Omit<User, 'id'>): Promise<void> {
    this.isLoading = true;
    try {
      const response = await fetch('/api/users', {
        method: 'POST',
        body: JSON.stringify(user)
      });
      const newUser = await response.json();
      // BUG: Race condition - if fetchUsers() is called while this is running,
      // the new user might not be in the final list
      this.users.push(newUser);
    } finally {
      this.isLoading = false;
    }
  }

  getUsers(): User[] {
    return this.users;
  }
}
```

What's the bug and how would you fix it?

